window.__saMergeCourse({id:'class10-math', title:'Mathematics', urdu:'ریاضی', class:'Class 10',
desc:'Quadratic equations, variations, sets, statistics, trigonometry and circle geometry — full Class 10 Maths.',
icon:'📐', chapters:[
{id:'c10-mat-ch10', title:'Tangent to a Circle', urdu:'دائرے کا مماس', comingSoon:false, lessons:[
{id:'c10-mat-ch10-l1', title:'What is a Tangent?', html:`<h3>Definitions</h3><ul><li><strong>Tangent:</strong> a line that touches the circle at exactly <strong>one point</strong> (the point of contact).</li><li><strong>Secant:</strong> a line cutting the circle at two points.</li><li><strong>Normal:</strong> the line perpendicular to the tangent at the point of contact — it passes through the centre.</li></ul><h3>Tangents from a point</h3><ul><li>From a point <strong>inside</strong>: no tangent.</li><li>From a point <strong>on</strong> the circle: exactly <strong>one</strong> tangent.</li><li>From a point <strong>outside</strong>: exactly <strong>two</strong> tangents.</li></ul><h3>Theorem 1</h3><p><em>The tangent at any point of a circle is perpendicular to the radius through the point of contact.</em> So ∠ between tangent and radius = 90° — the most-used fact in tangent problems.</p>`},
{id:'c10-mat-ch10-l2', title:'Two Tangents from an External Point', html:`<h3>Theorem 2</h3><p><em>The two tangents drawn from an external point to a circle are equal in length.</em></p><h4>Proof sketch</h4><p>Let tangents from P touch at A and B, O the centre. In right triangles OAP and OBP (right-angled at A, B by Theorem 1): OA = OB (radii), OP common → congruent by RHS → PA = PB. ∎</p><h3>Theorem 3</h3><p><em>The line joining the external point to the centre bisects the angle between the two tangents (and bisects the angle subtended at the centre).</em> So OP bisects ∠APB.</p><h4>Worked example</h4><p><em>Tangents from P are 12 cm; OP = 13 cm. Find the radius.</em></p><p>Right ΔOAP: r = √(OP² − PA²) = √(169 − 144) = √25 = <strong>5 cm</strong>.</p>`},
{id:'c10-mat-ch10-l3', title:'Alternate Segment Theorem and Applications', html:`<h3>Theorem 4 — Alternate segment theorem</h3><p><em>The angle between a tangent and a chord through the point of contact equals the angle in the alternate segment.</em></p><p>If tangent at A meets chord AB, then ∠ between tangent and AB = angle that AB subtends in the <strong>opposite</strong> arc.</p><h3>Worked example</h3><p><em>Tangent at A, chord AB; the angle in the alternate segment is 55°. Find the angle between tangent and AB.</em> Answer: <strong>55°</strong> directly.</p><h3>Exam strategy</h3><ul><li>Mark every radius-to-contact as 90°.</li><li>Look for the two equal tangents from each external point.</li><li>Alternate segment theorem converts tangent-chord angles into ordinary circle angles.</li></ul><p><strong>Exam tip:</strong> Always state the theorem name before using it — "by the alternate segment theorem…" earns the method mark.</p>`}
], quiz:[
{q:'A tangent touches a circle at ___ point(s):', options:['0','1','2','3'], answer:1, explain:'Exactly one point of contact defines a tangent.'},
{q:'The angle between a tangent and the radius at contact is:', options:['45°','60°','90°','180°'], answer:2, explain:'The tangent is perpendicular to the radius.'},
{q:'From an exterior point, the number of tangents to a circle is:', options:['0','1','2','Infinite'], answer:2, explain:'Two tangents can be drawn from an outside point.'},
{q:'The two tangents from an external point are:', options:['Perpendicular','Equal in length','Parallel','Unequal'], answer:1, explain:'Theorem 2: PA = PB.'},
{q:'If PA = 12 cm and OP = 13 cm, the radius is:', options:['5 cm','6 cm','25 cm','1 cm'], answer:0, explain:'r = √(169−144) = 5 cm.'},
{q:'The alternate segment theorem relates the tangent-chord angle to:', options:['The centre angle','The angle in the alternate segment','The radius','The diameter'], answer:1, explain:'It equals the angle in the opposite arc.'},
{q:'A line cutting a circle at two points is a:', options:['Tangent','Secant','Normal','Chord only'], answer:1, explain:'A secant intersects at two points.'},
{q:'The normal at the point of contact:', options:['Is parallel to the tangent','Passes through the centre','Touches at two points','Is the diameter'], answer:1, explain:'The normal is perpendicular to the tangent, through the centre.'},
{q:'The line OP from external point P to centre O:', options:['Is the longest tangent','Bisects the angle between the tangents','Is perpendicular to both','Equals the diameter'], answer:1, explain:'Theorem 3: OP bisects ∠APB.'},
{q:'No tangent can be drawn from a point:', options:['Outside the circle','On the circle','Inside the circle','At the centre only'], answer:2, explain:'Interior points have no tangents.'}
]}]
});
window.__saMergeCourse({id:'class10-math', title:'Mathematics', urdu:'ریاضی', class:'Class 10',
desc:'Quadratic equations, variations, sets, statistics, trigonometry and circle geometry — full Class 10 Maths.',
icon:'📐', chapters:[
{id:'c10-mat-ch11', title:'Chords and Arcs', urdu:'وتریں اور قوسین', comingSoon:false, lessons:[
{id:'c10-mat-ch11-l1', title:'Arcs and Central Angles', html:`<h3>Definitions</h3><ul><li><strong>Minor arc:</strong> the smaller part of the circumference between two points.</li><li><strong>Major arc:</strong> the larger part.</li><li><strong>Central angle:</strong> angle subtended by an arc at the centre.</li><li><strong>Congruent arcs:</strong> arcs of the same (or congruent) circles with equal length/measure.</li></ul><h3>Theorem 1</h3><p><em>In the same circle (or congruent circles), congruent arcs subtend congruent angles at the centre.</em></p><h3>Theorem 2 — Converse</h3><p><em>In the same circle (or congruent circles), congruent central angles intercept congruent arcs.</em></p><p>Together: arc measure ⟷ central angle measure — they match one-to-one. This is why we measure arcs in degrees.</p>`},
{id:'c10-mat-ch11-l2', title:'Arcs and Angles at the Circumference', html:`<h3>Theorem 3</h3><p><em>In the same circle (or congruent circles), congruent arcs subtend congruent angles at the circumference.</em></p><h3>Theorem 4 — Converse</h3><p><em>Angles at the circumference subtending congruent arcs are congruent — equivalently, congruent angles at the circumference stand on congruent arcs.</em></p><h4>Why it matters</h4><p>These theorems let you transfer information between arcs and angles freely: equal arcs → equal angles (at centre or circumference), and back. They are the foundation of the next chapter (angle in a segment).</p><h4>Worked example</h4><p><em>Two arcs AB and CD of the same circle subtend 40° and 40° at the centre. What can you say about the angles they subtend at the circumference?</em> The arcs are congruent, so the circumference angles standing on them are <strong>equal</strong>.</p>`},
{id:'c10-mat-ch11-l3', title:'Parallel Chords and Arcs Between Them', html:`<h3>Theorem 5</h3><p><em>Parallel chords of a circle intercept congruent arcs between them.</em> If AB ∥ CD, then arc AC = arc BD (the arcs "between" the parallels).</p><h4>Proof sketch</h4><p>Join AD (a transversal). Alternate angles: ∠ADC = ∠BAD. By Theorem 4's converse, equal circumference angles stand on equal arcs → arc AC = arc BD. ∎</p><h3>Worked example</h3><p><em>AB ∥ CD in a circle; arc AC = 70°. Find arc BD.</em> By Theorem 5, arc BD = <strong>70°</strong>.</p><h3>Summary of the chapter's logic</h3><ul><li>Equal arcs ⟺ equal central angles.</li><li>Equal arcs ⟺ equal circumference angles.</li><li>Parallel chords ⟹ equal intercepted arcs.</li></ul><p><strong>Exam tip:</strong> Quote "parallel chords intercept equal arcs" whenever you see ∥ inside a circle.</p>`}
], quiz:[
{q:'The larger part of the circumference between two points is the:', options:['Minor arc','Major arc','Chord','Sector'], answer:1, explain:'Major arc = the larger portion.'},
{q:'Congruent arcs subtend ___ at the centre:', options:['Supplementary angles','Congruent angles','Right angles','Zero angle'], answer:1, explain:'Equal arcs give equal central angles.'},
{q:'If two central angles are equal, the arcs are:', options:['Supplementary','Congruent','Parallel','Unequal'], answer:1, explain:'Converse: equal central angles → equal arcs.'},
{q:'Congruent arcs subtend ___ at the circumference:', options:['Unequal angles','Congruent angles','Obtuse angles','Straight angles'], answer:1, explain:'Equal arcs give equal circumference angles.'},
{q:'Parallel chords of a circle intercept:', options:['Unequal arcs','Congruent arcs','Diameters','Tangents'], answer:1, explain:'The arcs between parallel chords are equal.'},
{q:'AB ∥ CD and arc AC = 70°; arc BD equals:', options:['35°','70°','140°','110°'], answer:1, explain:'Parallel chords intercept congruent arcs.'},
{q:'Arc measure is usually expressed in:', options:['Centimetres','Degrees','Litres','Radians only'], answer:1, explain:'Arcs are measured by their central angle in degrees.'},
{q:'A central angle is subtended at the:', options:['Circumference','Centre','Chord','Tangent'], answer:1, explain:'Central angle has its vertex at the centre.'},
{q:'If arc PQ = arc RS, then ∠POQ ___ ∠ROS:', options:['>','<','=','is supplementary to'], answer:2, explain:'Congruent arcs subtend congruent central angles.'},
{q:'The foundation for "angle in a segment" theorems is:', options:['Tangent theorems','Chords-and-arcs angle relations','Pythagoras','Statistics'], answer:1, explain:'Arc–angle relations lead directly to segment-angle theorems.'}
]}]
});
window.__saMergeCourse({id:'class10-math', title:'Mathematics', urdu:'ریاضی', class:'Class 10',
desc:'Quadratic equations, variations, sets, statistics, trigonometry and circle geometry — full Class 10 Maths.',
icon:'📐', chapters:[
{id:'c10-mat-ch12', title:'Angle in a Segment', urdu:'قطعے میں زاویہ', comingSoon:false, lessons:[
{id:'c10-mat-ch12-l1', title:'Central Angle vs Circumference Angle', html:`<h3>Segment of a circle</h3><p>A chord divides a circle into two <strong>segments</strong>: the <strong>minor segment</strong> (smaller) and the <strong>major segment</strong> (larger). An angle "in" a segment has its vertex on the arc of that segment.</p><h3>Theorem 1 — The double-angle theorem</h3><p><em>The measure of a central angle is double the measure of any angle at the circumference standing on the same arc.</em></p><blockquote>∠AOB = 2 × ∠ACB &nbsp; (same arc AB)</blockquote><h4>Proof sketch</h4><p>Join OC. In isosceles ΔOAC (OA = OC), base angles are equal; exterior angle ∠AOD = 2∠ACO. Similarly ∠BOD = 2∠BCO. Adding: ∠AOB = 2∠ACB. ∎</p><p>This single theorem powers the rest of the chapter.</p>`},
{id:'c10-mat-ch12-l2', title:'Angles in the Same Segment', html:`<h3>Theorem 2</h3><p><em>Angles in the same segment of a circle are equal.</em></p><h4>Proof sketch</h4><p>Angles ∠ACB and ∠ADB stand on the same arc AB. By Theorem 1, each equals half the central angle ∠AOB — hence they are equal to each other. ∎</p><h3>Theorem 3 — Angle in a semicircle</h3><p><em>The angle in a semicircle is a right angle.</em></p><h4>Proof sketch</h4><p>The diameter subtends a central angle of 180°; the circumference angle is half of that: 180°/2 = <strong>90°</strong>. ∎</p><h4>Worked example</h4><p><em>AB is a diameter; C is on the circle. If ∠CAB = 30°, find ∠CBA.</em> ∠ACB = 90° (semicircle) → ∠CBA = 180° − 90° − 30° = <strong>60°</strong>.</p>`},
{id:'c10-mat-ch12-l3', title:'Converse Theorems and Problem Solving', html:`<h3>Theorem 4 — Converse of same-segment</h3><p><em>If two points on the same side of a line segment subtend equal angles at the segment's endpoints, the four points are concyclic (lie on one circle).</em> Used to prove points lie on a circle.</p><h3>Theorem 5 — Converse of semicircle angle</h3><p><em>If an angle subtended by a segment at a point is a right angle, the point lies on the circle with the segment as diameter.</em></p><h3>Problem-solving toolkit</h3><ul><li>Spot the <strong>diameter</strong> → write 90° immediately.</li><li>Spot <strong>equal angles on the same chord</strong> → same segment.</li><li>Convert: circumference angle → <strong>double</strong> for the central angle.</li></ul><p><strong>Exam tip:</strong> Mark the centre O and join radii — most angle-chasing solutions start there.</p>`}
], quiz:[
{q:'A central angle standing on the same arc as a 35° circumference angle measures:', options:['35°','70°','17.5°','140°'], answer:1, explain:'Central = 2 × circumference = 70°.'},
{q:'Angles in the same segment are:', options:['Supplementary','Equal','Complementary','Unequal'], answer:1, explain:'Each equals half the same central angle.'},
{q:'The angle in a semicircle is:', options:['45°','60°','90°','180°'], answer:2, explain:'Half of the 180° central angle of a diameter.'},
{q:'AB is a diameter and C is on the circle; ∠ACB equals:', options:['45°','90°','60°','Depends on C'], answer:1, explain:'Angle in a semicircle is always 90°.'},
{q:'If ∠ACB = ∠ADB with C, D on the same side of AB, then A, B, C, D are:', options:['Collinear','Concyclic','Parallel','Coincident'], answer:1, explain:'Converse of the same-segment theorem.'},
{q:'A chord subtends 50° at the circumference; at the centre it subtends:', options:['25°','50°','100°','130°'], answer:2, explain:'Double: 2 × 50° = 100°.'},
{q:'The minor segment is the:', options:['Larger part','Smaller part cut off by a chord','Diameter','Centre region'], answer:1, explain:'A chord creates minor (small) and major (large) segments.'},
{q:'In the proof of the double-angle theorem, ΔOAC is:', options:['Equilateral','Isosceles (OA = OC)','Scalene','Right-angled'], answer:1, explain:'OA and OC are both radii.'},
{q:'If an angle subtended by segment PQ at point R is 90°, R lies:', options:['Inside the circle','On the circle with PQ as diameter','Outside always','At the centre'], answer:1, explain:'Converse of the semicircle-angle theorem.'},
{q:'Two angles 40° and 40° stand on chord XY from the same side; the four endpoints:', options:['Form a line','Lie on one circle','Are the diameter ends','Coincide'], answer:1, explain:'Equal angles on the same segment imply concyclic points.'}
]}]
});
